INSERT INTO "exercises" ("id", "task", "prompt", "content_hash", "source_url", "image_url", "is_image_based", "first_seen_on", "last_seen_on") VALUES
('2026-09-t2-p001-s001', 2, 'Je suis votre nouveau voisin. Vous voulez savoir comment fonctionne le tri des déchets dans l''immeuble. Vous me posez des questions (jours de collecte, poubelles, encombrants).', 'c5e8f48e4c08b31d0031eb218cc80a28ff59e7b89d15002ffbd53808195c3593', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
('2026-09-t2-p001-s002', 2, 'Je travaille dans une agence immobilière. Vous cherchez un logement à louer près de votre travail. Vous me posez des questions sur les appartements disponibles (loyer, surface, quartier, charges).', '1ac7f1eee07b82d9951a8df05c5a7e909c1ec88dd2e90e5fd9d136c977538772', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
('2026-09-t2-p001-s003', 2, 'Je suis le responsable d''une salle de sport. Vous souhaitez vous inscrire. Vous me posez des questions sur les abonnements, les horaires et les cours proposés.', '0e2eb37c938a57cfd5374d3fef202ff102d61bbe1e2a0aa4eaa7c8c9be7d8736', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
('2026-09-t2-p001-s004', 2, 'Je suis un(e) collègue qui revient d''un voyage au Québec. Vous préparez vous aussi un séjour là-bas. Vous me posez des questions pour organiser votre voyage (transport, hébergement, activités).', 'c46baed7c3f9ca309261142b18a51cb7c34f58c73a6db3884b9ccad0a6d0ec21', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
('2026-09-t2-p002-s001', 2, 'Je travaille à la bibliothèque municipale. Vous venez d''arriver dans la ville. Vous me posez des questions sur l''inscription et les services de la bibliothèque.', '5db2966aa53a9b4d185887739e27e9aa91ef0ac4dbe9ecc41e47a049ec8c2b6b', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
('2026-09-t2-p002-s002', 2, 'Je suis le propriétaire du logement que vous louez. Le chauffage ne fonctionne plus. Vous m''appelez pour régler le problème et vous me posez des questions sur la réparation.', '338752ea368f32d79927799f2f994cdbd56897415e8c26d45aa5a9b69c662e69', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
('2026-09-t2-p002-s003', 2, 'Je suis organisateur d''un festival de musique en plein air. Vous voulez y participer comme bénévole. Vous me posez des questions sur les missions, les horaires et les avantages.', '79c4c32ecb201885ff8a00718beb7fb3a6d4f86042bf730126f218fec4d59b11', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
('2026-09-t2-p002-s004', 2, 'Je suis un(e) ami(e) qui fait du covoiturage chaque semaine. Vous aimeriez essayer. Vous me posez des questions sur le fonctionnement, le prix et la sécurité.', 'f3403bd99d985b3c71239e2a5853170cafc4b1335e4ec0f85b49f5ccf910322e', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
('2026-09-t2-p003-s001', 2, 'Je travaille dans une école de langues. Vous voulez améliorer votre anglais. Vous me posez des questions sur les cours, les niveaux et les tarifs.', '801b3235c42bab301b8d1b2550a9d05980bcc1f8e3ce3bf61d7a32b58041a075', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
('2026-09-t2-p003-s002', 2, 'Je suis vendeur dans un magasin d''électroménager. Vous voulez acheter un réfrigérateur. Vous me posez des questions sur les modèles, la livraison et la garantie.', 'c5cdf276760eb702f0f9443cf5480b764aef0d485729255d90ef68c95919fb48', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
('2026-09-t2-p003-s003', 2, 'Je suis responsable d''un jardin communautaire. Vous voulez cultiver une parcelle. Vous me posez des questions sur les conditions, le prix et les règles du jardin.', 'a1af076b2a82be00b23c62b58b1c508bc5ca7ac73f27268d0cf8b18186fb1d49', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
('2026-09-t2-p003-s004', 2, 'Je suis un(e) ami(e) qui a adopté un chien récemment. Vous pensez faire la même chose. Vous me posez des questions sur l''adoption et la vie avec un animal.', '0f48af3f973f66fedbdad3e50a62d2cb161d8473714a028b5e86280a402d2b85', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
('2026-09-t3-p001-s001', 3, 'Selon vous, le télétravail améliore-t-il la qualité de vie des salariés ? Donnez votre opinion en vous appuyant sur des exemples.', '555eec25805b6ed4e0c97899eaeb77c872f346522214032d8ac2924a29395b16', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
('2026-09-t3-p001-s002', 3, 'Certaines villes interdisent les voitures dans leur centre. Pensez-vous que c''est une bonne idée ? Justifiez votre point de vue.', '2b3883641a942cd7d2114ee1d1338121296cd7cfdf50892627e87cd3d4fbb388', 'https://github.com/yortyrh/parle-tcf/blob/main/packages/db/seed/README.md', NULL, FALSE, '2026-09-01', '2026-09-01'),
